function libraryScrollKey(page=cardPage,section=collectionPage){return page==='decks'?'decks':page+':'+section;}
function cardSection(id){if(!['decks','collection'].includes(id))return;libraryScroll[libraryScrollKey()]=$('cardsScroll').scrollTop;cardPage=id;renderCollection();$('cardsScroll').scrollTop=libraryScroll[libraryScrollKey(id)]||0;}
function librarySection(id){if(!U.collectionSections.some(s=>s.id===id))return;libraryScroll[libraryScrollKey()]=$('cardsScroll').scrollTop;cardPage='collection';collectionPage=id;renderCollection();$('cardsScroll').scrollTop=libraryScroll['collection:'+id]||0;}
function magicArt(item){return icon(item.icon,'magic-item-art',item.name);}
let previewScenes=null;
async function renderSkinPreviews(parent){const canvases=[...parent.querySelectorAll('canvas[data-skin-preview]')];if(!canvases.length)return;try{previewScenes=previewScenes||native.ensureScenes(['building_tower','chr_king','chr_princess','tower_skins']);await previewScenes;for(const cv of canvases){if(!cv.isConnected)continue;const ct=cv.getContext('2d');ct.clearRect(0,0,cv.width,cv.height);ct.save();ct.translate(cv.width/2,cv.height*.81);ct.scale(2,2);native.drawTower(ct,{x:0,y:0,preview:true,team:1,king:true,skin:cv.dataset.skinPreview,hp:1,active:false,heading:Math.PI/2},0);ct.restore();cv.dataset.rendered='true';cv.dataset.facing='front';}}catch(e){previewScenes=null;console.error(e);for(const cv of canvases)cv.setAttribute('aria-label','Tower preview failed to load');toast('Tower previews could not load. Reopen this page to retry.');}}
