 const node=$('onlineContent');if(!node)return;node.innerHTML=`<section class="online-soon-card">${icon('team-icon')}<h2>Online Play</h2><strong>Coming Soon</strong><p>Real-time matchmaking, friends and team battles will appear here in a future update.</p><div class="online-soon-features"><span>1v1</span><span>2v2</span><span>3v3</span><span>5v5</span></div></section>`;hydrate(node);
