 $('roadArenaJump').onchange=e=>{const el=$('roadScroll').querySelector('[data-road-id="'+CSS.escape(e.target.value)+'"] .road-gate');if(el)$('roadScroll').scrollTop+=el.getBoundingClientRect().top-$('roadScroll').getBoundingClientRect().top-25;};
