 for(const select of $('modalPanel').querySelectorAll('[data-graphics]'))select.addEventListener('change',()=>{profile.graphics=RoyaleGraphics.normalize({...profile.graphics,[select.dataset.graphics]:select.value});RoyaleGraphics.apply(profile.graphics);native.releaseArenaCache?.();RoyaleCustomArena.clear();native.towerShadowCache?.clear();lastHomePaint=-Infinity;save();});
