 for(const el of $('hand').children){const slot=Number(el.dataset.slot),c=battle.card(0,slot);el.classList.toggle('unaffordable',battle.elixir[0]+.00001<c.cost);const remaining=Math.max(0,battle.slotReady[0][slot]-battle.time),cycling=el.querySelector('.cycling');cycling.hidden=remaining<=0;cycling.style.height=Math.min(100,remaining/Math.max(.01,Number(C.DATA.globals.SPELL_DEPLOY_DELAY?.NumberValue||1000)/1000)*100)+'%';el.disabled=Boolean(battle.tiebreaker);el.setAttribute('aria-disabled',String(Boolean(battle.tiebreaker)||remaining>0||battle.elixir[0]+.00001<c.cost));}
