    if(m.type==='done'||m.type==='error'){worker.terminate();await flushTraining();trainingWorker=null;const shouldLoop=m.type==='done'&&!m.cancelled&&!trainingSaveError&&trainingPreferences.loop;trainingState=m.type==='error'?'Training error: '+m.message:trainingSaveError?`${m.completed} finished · ${trainingPackets.length} not saved. ${trainingSaveError}`:shouldLoop?`Loop complete · ${m.completed} matches saved · restarting…`:`${m.cancelled?'Stopped':'Finished'} · ${m.completed} matches ${learningStore.persistent?'saved':'in session memory'}`;if(modal==='learning-center')learningMenu();if(shouldLoop)setTimeout(()=>trainStart(true),40);return;}
